mapper.select:
SELECT ps.id AS submissionId, pt.id AS taskId, pt.title AS taskTitle, ps.student_id AS studentId, su.name AS studentName, sc.id AS classId, sc.name AS className, ps.video_url AS videoUrl, ps.file_id AS fileId, ps.file_code AS fileCode, ps.create_time AS submitTime, CASE WHEN pf.id IS NULL THEN 0 ELSE 1 END AS feedbackStatus, pf.id AS feedbackId, pf.comment AS comment, pf.create_time AS feedbackTime FROM practice_submission ps INNER JOIN practice_task pt ON ps.task_id = pt.id AND pt.deleted = 0 INNER JOIN sys_user su ON ps.student_id = su.id AND su.deleted = 0 LEFT JOIN sys_class sc ON pt.class_id = sc.id AND sc.deleted = 0 LEFT JOIN practice_feedback pf ON ps.id = pf.submission_id AND pf.deleted = 0
ps.deleted = 0
AND ${ew.sqlSegment}

mapper.delete:
DELETE FROM practice_submission
WHERE deleted = 1
  AND IFNULL(update_time, create_time) < #{threshold}
